import{$ as e,B as t,o as n,z as r}from"./chunks/framework.BROBN02c.js";var i=JSON.parse(`{"title":"v3.11.0 基线核验报告：官方 v3.3.1 功能对齐 · 差距确认","description":"","frontmatter":{},"headers":[],"relativePath":"dev/parity-report-v3.11.0.md","filePath":"dev/parity-report-v3.11.0.md","lastUpdated":1795603101000}`),a={name:`dev/parity-report-v3.11.0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t('<h1 id="v3-11-0-基线核验报告-官方-v3-3-1-功能对齐-·-差距确认" tabindex="-1">v3.11.0 基线核验报告：官方 v3.3.1 功能对齐 · 差距确认 <a class="header-anchor" href="#v3-11-0-基线核验报告-官方-v3-3-1-功能对齐-·-差距确认" aria-label="Permalink to &quot;v3.11.0 基线核验报告：官方 v3.3.1 功能对齐 · 差距确认&quot;">​</a></h1><blockquote><p>生成时间：2026-11-25 · 核验人：开发代理（本地全量重跑，未采信任何口头结论） 基线：<strong>v3.10.2</strong>（main = b683ede8，远端 CI 全绿） 任务规格：<a href="./parity-plan">parity-plan.md</a> · 进度：<a href="./parity-progress">parity-progress.md</a></p></blockquote><h2 id="_0-核验环境与可复现命令" tabindex="-1">0. 核验环境与可复现命令 <a class="header-anchor" href="#_0-核验环境与可复现命令" aria-label="Permalink to &quot;0. 核验环境与可复现命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>环境</td><td>Linux 沙箱，Node v24.22.3，git 2.47.3，Xvfb present</td></tr><tr><td>包管理</td><td><code>corepack prepare pnpm@12.21.0 --activate</code>（与 CI 一致）</td></tr><tr><td>安装</td><td><code>pnpm install --frozen-lockfile --network-concurrency=32</code>（registry 走 npmmirror，integrity 由 lockfile sha512 保证，与 CI 内容等价）</td></tr><tr><td>构建门禁</td><td><code>pnpm exec turbo build</code>（CI zero-error gate 同款）</td></tr><tr><td>图标门禁</td><td><code>node scripts/check-icons.js</code></td></tr><tr><td>单元测试</td><td><code>node --test tests/unit/mirror.test.mjs</code></td></tr><tr><td>E2E</td><td><code>node tests/e2e/run-e2e.mjs</code>（真实构建产物 + Xvfb + fake adb :5037/:5038 + mock LLM :5039/:5040 + CDP 驱动）</td></tr><tr><td>文案落地率</td><td>见第 2 节脚本（hyphen-aware 正则 `(?:automation</td></tr></tbody></table><h2 id="_1-本地构建基线-全部重跑验证" tabindex="-1">1. 本地构建基线（全部重跑验证） <a class="header-anchor" href="#_1-本地构建基线-全部重跑验证" aria-label="Permalink to &quot;1. 本地构建基线（全部重跑验证）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>门禁</th><th>结果</th><th>说明</th></tr></thead><tbody><tr><td><code>pnpm install --frozen-lockfile</code></td><td>✅ 4m06s 完成</td><td>lockfile 未做任何修改（pnpm 12 双文档格式保持原样）</td></tr><tr><td><code>pnpm exec turbo build</code></td><td>✅ 6/6 tasks，零错误</td><td>全部页面 + workspace 包构建成功</td></tr><tr><td><code>node scripts/check-icons.js</code></td><td>✅ 88/88</td><td>图标门禁全过</td></tr><tr><td><code>node --test tests/unit/mirror.test.mjs</code></td><td>✅ 14/14</td><td>scrcpy 帧解析、控制消息编码、键位映射校验</td></tr><tr><td><code>node tests/e2e/run-e2e.mjs</code></td><td>✅ <strong>73/73</strong></td><td>S1–S13 全场景通过（对话重连、定时任务、群控广播、OpenCV 识图、多设备 AI、内嵌镜像、工作流画布、网页端）</td></tr></tbody></table><p><strong>结论：v3.10.2 的&quot;73 项 e2e 全绿&quot;声明与事实一致（本地独立复跑通过）。</strong></p><h2 id="_2-文案落地率-hyphen-aware-重跑" tabindex="-1">2. 文案落地率（hyphen-aware 重跑） <a class="header-anchor" href="#_2-文案落地率-hyphen-aware-重跑" aria-label="Permalink to &quot;2. 文案落地率（hyphen-aware 重跑）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前缀</th><th>总数</th><th>已引用</th><th>未引用</th><th>落差</th></tr></thead><tbody><tr><td><code>automation.*</code></td><td>170</td><td>30</td><td><strong>140</strong></td><td>官方自动化脚本编辑器整页缺失</td></tr><tr><td><code>mirror.*</code></td><td>31</td><td>5</td><td><strong>26</strong></td><td>多设备同屏 + 首用指引 + 输入条 + 快捷键文案缺失</td></tr><tr><td><code>device.control.*</code></td><td>128</td><td>114</td><td><strong>14</strong></td><td>文件管理器细节、音量命名、&quot;去查看&quot;、启动设置、多屏提示</td></tr></tbody></table><p>方法学说明：</p><ul><li>本仓库 zh-CN.json 共 <strong>1585 条</strong>（官方 deb 为 1305 条；差额为 fork 自身新增 key：device.schedule.<em>、tasks.</em>、group.<em>、copilot.settings.</em> 等）。<code>automation.*</code>（170）与 <code>mirror.*</code>（31）计数与官方<strong>完全一致</strong>，证明官方这两组 key 在 fork 中原样保留、未被实现。</li><li><code>device.control.*</code> 本地 128 vs 官方 130，差 2 条（本地文件不含）→ 待官方 deb 下载复核（open item，见第 10 节）。</li><li><code>device.schedule.*</code>（计划任务 30+ 条未引用）与 <code>copilot.config/check/batch</code> 等未引用 key 属于<strong>上游公开源码遗留文案</strong>，已被本 fork 的 tasks 模块与自研 Copilot 替代实现，不计入对齐缺口。</li></ul><h2 id="_3-执行器步骤类型对表-executor-js-case" tabindex="-1">3. 执行器步骤类型对表（executor.js <code>case</code>） <a class="header-anchor" href="#_3-执行器步骤类型对表-executor-js-case" aria-label="Permalink to &quot;3. 执行器步骤类型对表（executor.js `case`）&quot;">​</a></h2><p><strong>已有 18 种</strong>：<code>tap</code> <code>swipe</code> <code>input_text</code> <code>key</code> <code>shell</code>（=官方 command）<code>open_app</code>（=launch，无强停）<code>screenshot</code> <code>wait_image</code> <code>match_image</code> <code>notify</code> <code>http</code> <code>list_devices</code> <code>get_device_info</code> <code>get_ui_layout</code> <code>broadcast_tap</code> <code>broadcast_key</code> <code>broadcast_input_text</code> <code>broadcast_screenshot</code></p><p><strong>对照官方 1.1 的缺口</strong>：</p><table tabindex="0"><thead><tr><th>缺口</th><th>官方语义</th><th>影响</th></tr></thead><tbody><tr><td><code>wait</code> 步骤</td><td>纯延时步骤类型</td><td>P0-B</td></tr><tr><td><code>install</code> 步骤</td><td>APK 路径 + 可选先卸载（<code>adb install -r</code> / <code>pm uninstall</code>）</td><td>P0-B</td></tr><tr><td><code>record</code> 步骤</td><td>screenrecord，来源=屏幕/摄像头、时长、保存目录</td><td>P0-B</td></tr><tr><td><code>loop</code> 步骤</td><td>循环次数包裹子步骤</td><td>P0-B</td></tr><tr><td><code>condition</code> 步骤</td><td>条件分组：图像存在/设备在线/变量比较</td><td>P0-B</td></tr><tr><td><code>launch</code> 强停</td><td><code>am force-stop</code> 后再 <code>monkey -p ... 1</code></td><td>P0-B</td></tr><tr><td>步骤公共字段</td><td><code>delayBefore</code> / <code>loopCount</code> / <code>randomRange</code>（坐标 n×5px、时间 n×500ms，0=禁用）</td><td>P0-B</td></tr></tbody></table><h2 id="_4-官方「自动化脚本编辑器」能力对照-1-1-→-现状-→-证据" tabindex="-1">4. 官方「自动化脚本编辑器」能力对照（1.1 → 现状 → 证据） <a class="header-anchor" href="#_4-官方「自动化脚本编辑器」能力对照-1-1-→-现状-→-证据" aria-label="Permalink to &quot;4. 官方「自动化脚本编辑器」能力对照（1.1 → 现状 → 证据）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>官方能力</th><th>现状</th><th>证据</th></tr></thead><tbody><tr><td>脚本管理（列表/新建/删除确认/保存/按设备）</td><td>❌ 缺</td><td>无 <code>pages/automation/</code>；tasks 模块是&quot;定时任务+工作流&quot;，非按设备的可编辑脚本</td></tr><tr><td>导入导出（替换确认）</td><td>❌ 缺</td><td>无 automation.script.import/export 实现</td></tr><tr><td>步骤类型 10 种 + 公共字段</td><td>部分</td><td>executor 18 种见第 3 节；<code>delayBefore/loopCount/randomRange</code> 全缺（grep MISS）</td></tr><tr><td>步骤分组（基础/条件/扩展）</td><td>❌ 缺</td><td>无 group.basic/conditional/extended 引用</td></tr><tr><td>识图判断（imageMatch 挂任意步骤）</td><td>✅ 已有</td><td>v3.9.0：templatePath/threshold/followMatchPoint/未匹配跳过（e2e S11.5 实测 TM_CCOEFF_NORMED）</td></tr><tr><td>智能拾取（实时截图裁剪/取坐标/画轨迹）</td><td>❌ 缺</td><td>模板上传+即时测试有；<code>automation.picker.*</code> 0/2 引用</td></tr><tr><td>执行控制（单步/选中/全量/暂停/继续/停止/状态机）</td><td>❌ 缺（任务级有启停）</td><td><code>automation.run.*</code> 0/14 引用；grep 单步/暂停（脚本级）MISS</td></tr><tr><td>执行日志（独立面板/清空/逐条状态）</td><td>部分</td><td>任务运行历史有（run-history + /api/runs），非脚本执行日志面板</td></tr><tr><td>批量执行（变量注入表格/添加行/终止）</td><td>❌ 缺</td><td><code>automation.batch.*</code> 0/8 引用</td></tr><tr><td>魔法变量（自定义 CRUD/内置 4 种/{var} 语法）</td><td>❌ 缺</td><td><code>automation.magic.*</code> 0/22 引用；grep 无 {var} 解析器</td></tr><tr><td>模板库（4 套官方模板/从模板创建）</td><td>❌ 缺</td><td><code>automation.template.*</code> 0/18 引用</td></tr><tr><td>内置按键（返回/删除/回车/主页/菜单/电源/最近任务/音量±）</td><td>部分</td><td>group-control 窗口有部分按键；脚本步骤的 key 选择器无内置键位表</td></tr></tbody></table><h2 id="_5-官方「群控镜像」能力对照-1-2-→-现状-→-证据" tabindex="-1">5. 官方「群控镜像」能力对照（1.2 → 现状 → 证据） <a class="header-anchor" href="#_5-官方「群控镜像」能力对照-1-2-→-现状-→-证据" aria-label="Permalink to &quot;5. 官方「群控镜像」能力对照（1.2 → 现状 → 证据）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>官方能力</th><th>现状</th><th>证据</th></tr></thead><tbody><tr><td>单窗口承载 N 台设备 + 「打开所有设备」</td><td>❌ 缺</td><td>mirror 窗口单设备（session.js 每设备一条 session）；<code>mirror.devices</code>/<code>mirror.header.openAllDevices</code> 0 引用</td></tr><tr><td>主控手势广播到设备组</td><td>部分</td><td>group-control 窗口可广播（无视频画面）；mirror 窗口不广播</td></tr><tr><td>首次使用三步指引（可不再提示）</td><td>❌ 缺</td><td><code>mirror.guide.*</code> 0/15 引用</td></tr><tr><td>置顶/取消置顶、全屏/退出全屏</td><td>✅ 已有</td><td>v3.10.0 镜像窗口体验（但 <code>mirror.header.exitAlwaysOnTop/exitFullscreen</code> 文案用的是自有 key）</td></tr><tr><td>输入条 + Enter 发送 + 关闭</td><td>❌ 缺</td><td><code>mirror.input.*</code> 0/4 引用</td></tr><tr><td>返回/主页/最近任务快捷键</td><td>✅ 功能有</td><td>v3.10.0 快捷指令（文案用自有 key）</td></tr><tr><td>连接中/已断开/重新连接</td><td>✅ 已有</td><td>连接状态/错误重试（v3.10.0）</td></tr><tr><td>技术底座</td><td>✅ 已有</td><td>WebCodecs optimizeForLatency + CSD 拼接 + 丢帧保护 + konva + scrcpy:* 通道（e2e S12 实测）</td></tr></tbody></table><h2 id="_6-官方-device-control-缺口-14-条未引用" tabindex="-1">6. 官方 device.control 缺口（14 条未引用） <a class="header-anchor" href="#_6-官方-device-control-缺口-14-条未引用" aria-label="Permalink to &quot;6. 官方 device.control 缺口（14 条未引用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>key</th><th>官方语义</th><th>现状</th></tr></thead><tbody><tr><td><code>capture.success.message</code></td><td>截图成功后&quot;是否前往截屏位置查看&quot;</td><td>❌ 只提示成功，无&quot;去查看&quot;</td></tr><tr><td><code>file.manager.select.all/invert/none</code></td><td>全选/反选/取消全选</td><td>❌ 缺</td></tr><tr><td><code>file.manager.rename.success</code></td><td>重命名成功</td><td>❌ 缺重命名</td></tr><tr><td><code>file.manager.download.failed</code> / <code>upload.current.file</code></td><td>下载失败/上传进度</td><td>❌ 缺</td></tr><tr><td><code>file.push.error</code></td><td>推送文件失败重试提示</td><td>❌ 缺</td></tr><tr><td><code>gnirehtet.stop.success</code></td><td>停止服务成功</td><td>❌ 缺</td></tr><tr><td><code>launch.settings</code></td><td>启动设置（目标窗口选择）</td><td>❌ 缺</td></tr><tr><td><code>mirror-group.open/close/tips/appClose.tips</code></td><td>多屏协同开窗数/关闭/ROM 兼容提示</td><td>部分：v3.10.2 已实现多屏协同主体（<code>mirror-group.name</code> 已引用），细节提示文案 4 条待接</td></tr></tbody></table><h2 id="_7-官方-copilot-对等性-1-4-非-1-1-对象" tabindex="-1">7. 官方 Copilot 对等性（1.4，非 1:1 对象） <a class="header-anchor" href="#_7-官方-copilot-对等性-1-4-非-1-1-对象" aria-label="Permalink to &quot;7. 官方 Copilot 对等性（1.4，非 1:1 对象）&quot;">​</a></h2><p>自研版<strong>强于官方</strong>：多供应商 + 自定义 baseUrl/model/apiKey、工具循环、定时任务、上下文压缩、多设备对话、网页端同步、断线重连与错误隔离（e2e S3/S10 实测）。官方走 api.moark.com 网关无自定义入口。维持&quot;不弱于官方&quot;的验收口径即可，无新增缺口。</p><h2 id="_8-网页端现状-18-端点实测" tabindex="-1">8. 网页端现状（18 端点实测） <a class="header-anchor" href="#_8-网页端现状-18-端点实测" aria-label="Permalink to &quot;8. 网页端现状（18 端点实测）&quot;">​</a></h2><p>已有：设备列表 / 会话列表+删除 / 对话（SSE 流式+中止）/ 任务列表+运行+启停 / 运行历史 / 工作流列表+运行 / 镜像（状态+启动+停止+控制+SSE 码流+键位方案）/ 登录。 缺口（对齐第 5 节目标）：任务/工作流/脚本的<strong>创建与编辑</strong>（无 POST-create/PUT）、脚本工作台、群控面板、多设备同屏镜像、会话重命名/搜索/导出、消息重发/编辑、多模态上传、运行历史详情（每步耗时/IO）、供应商设置修改（apiKey 不回显）、移动端适配、SSE 心跳+断线重连、密码 bcrypt/限流/只读模式、空态/骨架/深色/i18n。</p><h2 id="_9-差距汇总-→-交付映射" tabindex="-1">9. 差距汇总 → 交付映射 <a class="header-anchor" href="#_9-差距汇总-→-交付映射" aria-label="Permalink to &quot;9. 差距汇总 → 交付映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>差距</th><th>规模</th><th>计划 tag</th></tr></thead><tbody><tr><td>automation 页面整页 + 执行控制 + 日志（140 条文案的工作清单已全部列于核验脚本输出，按 batch/magic/picker/run/script(s)/state/step/template 分组）</td><td>大</td><td>v3.11.1 (P0-A)</td></tr><tr><td>wait/install/record/launch强停/loop/condition + delayBefore/loopCount/randomRange</td><td>中</td><td>v3.11.2 (P0-B)</td></tr><tr><td>智能拾取 / 魔法变量 / 批量执行 / 模板库</td><td>中</td><td>v3.11.3 (P1)</td></tr><tr><td>AI 生成脚本 / 录制转脚本 / 断点续跑 / dry-run</td><td>中</td><td>v3.12.0</td></tr><tr><td>网页端 CRUD + 工作台 + 群控 + 镜像增强</td><td>大</td><td>v3.12.1</td></tr><tr><td>网页端安全/移动端/实时性 + 人性化</td><td>中</td><td>v3.12.2</td></tr><tr><td>镜像多设备同屏广播 + 多屏协同增强 + 镜像内启动 App</td><td>大</td><td>v3.13.0</td></tr></tbody></table><h2 id="_10-待复核项-open-items" tabindex="-1">10. 待复核项（open items） <a class="header-anchor" href="#_10-待复核项-open-items" aria-label="Permalink to &quot;10. 待复核项（open items）&quot;">​</a></h2><ol><li><strong>官方 deb 复核</strong>：重新下载官方 <code>Escrcpy-3.3.1-linux-amd64.deb</code>（123,461,804 字节，需 sha256 校验），核对 <code>device.control.*</code> 差 2 条 key 与 automation 步骤字段细节（randomRange 官方语义已由本地 locale 佐证）。安排：后台下载，v3.11.1 开工前完成。</li><li><code>automation.step.*</code> 52 条逐条对应 P0-A/P0-B 的 UI 字段清单（已含本报告第 4 节）。</li><li>人性化清单（第 6 节 plan）无既有实现，全部为新增项，随 v3.12.2 验收。</li></ol><hr><p><strong>差距确认结论</strong>：官方 v3.3.1 付费功能中，<strong>识图判断、镜像技术底座、多屏协同主体、群控广播（独立窗口）、多设备 AI 已具备</strong>；<strong>自动化脚本工作台整页、5 类步骤类型、智能拾取、魔法变量、批量执行、模板库、镜像多设备同屏、网页端完整 CRUD 为主要缺口</strong>。按 parity-plan 第 9 节节奏推进，v3.11.1 起逐 tag 交付。</p>',31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};